<?php use App\Services\BookingRules; $id=(int)$reservation['id'];$minutes=intdiv((new DateTimeImmutable($reservation['end_datetime'],new DateTimeZone('UTC')))->getTimestamp()-(new DateTimeImmutable($reservation['start_datetime'],new DateTimeZone('UTC')))->getTimestamp(),60);$pendingPayment=null;$hasPaidPayment=false;foreach($payments as $payment){if($payment['payment_status']==='paid')$hasPaidPayment=true;if($payment['payment_status']==='pending' && $pendingPayment===null)$pendingPayment=$payment;}$validPaymentTotal=preg_match('/\A(?:0|[1-9][0-9]{0,7})\.[0-9]{2}\z/',(string)$reservation['total_amount'])===1 && $reservation['total_amount']!=='0.00' && $reservation['currency']==='PHP';$formAccepted=$latestDocument && $latestDocument['status']==='accepted'; ?>
<?php
$paymentPeriodEnded = \App\Services\PaymentRules::paymentPeriodEnded($reservation['start_datetime']);
$paymentEligible = \App\Services\PaymentRules::canInitiate($reservation['status'], $reservation['total_amount'], $reservation['currency'], $latestDocument['status'] ?? null, $reservation['start_datetime']);
$latestPayment = $payments[0] ?? null;
$paymentState = $hasPaidPayment ? 'paid' : ($pendingPayment ? 'pending' : ($latestPayment['payment_status'] ?? 'unpaid'));
$displayTime = static fn(string $utc): string => (new DateTimeImmutable($utc, new DateTimeZone('UTC')))->setTimezone(new DateTimeZone(config('Booking')->timezone))->format('M j, Y, g:i A');
$reference = static function (?string $value): string { $value = (string) $value; if ($value === '') return 'Not received yet'; $short = mb_strlen($value) > 15 ? mb_substr($value, 0, 8) . '...' . mb_substr($value, -4) : $value; return '<span class="student-reference"><span title="' . esc($value, 'attr') . '">' . esc($short) . '</span><button type="button" class="copy-reference" data-reference="' . esc($value, 'attr') . '" aria-label="Copy full reference"><span class="material-symbols-outlined" aria-hidden="true">content_copy</span></button><span class="copy-feedback" role="status" aria-live="polite"></span></span>'; };
$methodNames = ['gcash'=>'GCash','card'=>'Card','bank_transfer'=>'Bank Transfer'];
?>
<div class="reservation-detail-page">
<a class="reservation-back" href="<?= site_url('borrower/reservations') ?>"><span class="material-symbols-outlined" aria-hidden="true">arrow_back</span> Back to My Reservations</a>
<header class="reservation-heading"><div><h1>Reservation #<?= $id ?></h1><p><?= esc(implode(', ', array_map(static fn($item) => ($item['catalog_group'] ?? '') ?: $item['name'], $items))) ?></p><?php if (!empty($reservation['created_at'])): ?><small>Submitted <?= esc($displayTime($reservation['created_at'])) ?> Manila</small><?php endif ?></div><div class="reservation-badges"><span class="status-badge <?= esc($reservation['status'],'attr') ?>"><?= esc(ucfirst($reservation['status'])) ?></span><span class="status-badge <?= esc($paymentState,'attr') ?>">Payment: <?= esc(ucfirst($paymentState)) ?></span></div></header>
<div class="student-workspace">
<section class="student-card"><h2>Reservation Information</h2><dl class="student-details"><div><dt>Start (Manila)</dt><dd><?= esc($displayTime($reservation['start_datetime'])) ?></dd></div><div><dt>End (Manila)</dt><dd><?= esc($displayTime($reservation['end_datetime'])) ?></dd></div><div><dt>Duration</dt><dd><?= intdiv($minutes,60) ?> hr <?= $minutes%60 ?> min</dd></div><div><dt>Purpose</dt><dd class="description"><?= esc($reservation['purpose']) ?></dd></div></dl></section>
<section class="student-card"><h2>Teacher-Signed Request Form</h2><?php if($latestDocument): ?><div class="reservation-attachment"><span class="material-symbols-outlined" aria-hidden="true">description</span><div><strong><?= esc($latestDocument['original_name']) ?></strong><small><?= number_format((int)$latestDocument['file_size']/1048576,2) ?> MiB</small><span class="status-badge <?= esc($latestDocument['status'],'attr') ?>"><?= esc(ucfirst($latestDocument['status'])) ?></span></div><a class="button secondary" href="<?= site_url('borrower/reservations/'.$id.'/documents/'.$latestDocument['id']) ?>">Download</a></div><?php if(!empty($latestDocument['rejection_reason'])): ?><p class="description">Administrator feedback: <?= esc($latestDocument['rejection_reason']) ?></p><?php endif ?><?php else: ?><p>No signed form has been recorded. Approval and payment require an accepted form.</p><?php endif ?><?php if($reservation['status']==='pending' && (!$latestDocument || $latestDocument['status']==='rejected')): ?><form method="post" enctype="multipart/form-data" action="<?= site_url('borrower/reservations/'.$id.'/form') ?>"><?= csrf_field() ?><label for="replacement_form">Upload <?= $latestDocument?'replacement ':'' ?>signed request form (PDF, JPG, or PNG)</label><input id="replacement_form" name="request_form" type="file" accept=".pdf,.jpg,.jpeg,.png,application/pdf,image/jpeg,image/png" required><small>Maximum size <?= number_format(config('ReservationDocuments')->maxFileSizeBytes/1048576,1) ?> MiB. The form will be reviewed by an administrator.</small><div class="student-actions"><button type="submit"><?= $latestDocument?'Resubmit':'Submit' ?> form for review</button></div></form><?php endif ?></section>
<section class="student-card student-wide"><h2>Reserved Resources</h2><div class="table-wrap"><table class="reservation-resource-table"><thead><tr><th>Resource</th><th>Quantity</th><th>Hourly rate</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= esc(!empty($item['catalog_group'])?$item['catalog_group']:$item['name']) ?></td><td><?= (int)$item['quantity'] ?></td><td>&#8369;<?= esc($item['rate_per_hour']) ?></td><td>&#8369;<?= esc($item['subtotal']) ?></td></tr><?php endforeach ?></tbody></table></div><p class="student-total">Total reservation fee: <?= $reservation['currency'] === 'PHP' ? '&#8369;' : esc($reservation['currency']).' ' ?><?= esc($reservation['total_amount']) ?></p></section>
<section id="payment-information" class="student-card student-wide reservation-payment"><h2>Payment Information</h2><?php if ($message = session()->getFlashdata('payment_success')): ?><p class="reservation-notice success" role="status"><?= esc($message) ?></p><?php endif ?><?php if ($message = session()->getFlashdata('payment_error')): ?><p class="reservation-notice failure" role="alert"><?= esc($message) ?></p><?php endif ?><p class="reservation-notice info"><span class="material-symbols-outlined" aria-hidden="true">info</span> Academic payment simulation: no real funds are transferred. Use fictional details only.</p>
<div class="reservation-payment-summary"><div><small>Total reservation fee</small><strong><?= $reservation['currency'] === 'PHP' ? '&#8369;' : esc($reservation['currency']).' ' ?><?= esc($reservation['total_amount']) ?></strong></div><div><small>Payment status</small><span class="status-badge <?= esc($paymentState,'attr') ?>"><?= esc(ucfirst($paymentState)) ?></span></div><?php if($latestPayment): ?><div><small>Latest method</small><?= esc($methodNames[$latestPayment['payment_method']] ?? $latestPayment['payment_method']) ?></div><div><small>Latest reference</small><?= $reference($latestPayment['transaction_reference'] ?? null) ?></div><?php if(!empty($latestPayment['paid_at']) || !empty($latestPayment['created_at'])): ?><div><small><?= !empty($latestPayment['paid_at']) ? 'Paid' : 'Attempted' ?></small><?= esc($displayTime(($latestPayment['paid_at'] ?? null) ?: $latestPayment['created_at'])) ?> Manila</div><?php endif ?><?php endif ?></div>
<?php if($payments): ?><h3>Transaction history</h3><div class="table-wrap"><table class="reservation-transactions"><thead><tr><th>Payment reference</th><th>Method</th><th>Status</th><th>Amount</th><th>Gateway reference</th><th>Receipt</th></tr></thead><tbody><?php foreach($payments as $payment): ?><tr><td><?= $reference($payment['transaction_reference'] ?? null) ?></td><td><?= esc($methodNames[$payment['payment_method']] ?? $payment['payment_method']) ?></td><td><span class="status-badge <?= esc($payment['payment_status'],'attr') ?>"><?= esc(ucfirst($payment['payment_status'])) ?></span></td><td><?= $payment['currency'] === 'PHP' ? '&#8369;' : esc($payment['currency']).' ' ?><?= esc($payment['amount']) ?></td><td><?= $reference($payment['gateway_transaction_id'] ?? null) ?></td><td><?php if($payment['payment_status'] !== 'pending'): ?><a href="<?= site_url('borrower/payments/'.$payment['id'].'/receipt') ?>"><?= $payment['payment_status'] === 'paid' ? 'View receipt' : 'View transaction details' ?></a><?php else: ?>&#8212;<?php endif ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
<?php if ($reservation['status'] === 'approved' && $paymentPeriodEnded && !$hasPaidPayment): ?><div class="reservation-notice pending" role="status"><div><strong>Payment period has ended</strong><p>The scheduled reservation period has already passed. You can no longer initiate or continue payment for this reservation.</p><p>Your previous transactions remain available in your payment history.</p><a href="<?= site_url('borrower/resources') ?>">Browse Resources</a></div></div><?php if ($pendingPayment): ?><form class="payment-recovery-form" method="post" action="<?= site_url('borrower/reservations/'.$id.'/payments/'.$pendingPayment['id'].'/verify') ?>"><?= csrf_field() ?><button type="submit" class="secondary" data-busy="Checking status...">Check Status</button></form><?php endif ?><?php elseif($paymentEligible && !$hasPaidPayment && !$pendingPayment): ?><?php if ($latestPayment && in_array($latestPayment['payment_status'], ['failed', 'declined', 'cancelled', 'expired'], true)): ?><p class="reservation-notice failure" role="status"><span class="material-symbols-outlined" aria-hidden="true">error</span> The latest attempt was <?= esc($latestPayment['payment_status']) ?>. You may start another payment.</p><?php endif ?><form method="post" action="<?= site_url('borrower/reservations/'.$id.'/payments') ?>" class="payment-form"><?= csrf_field() ?><fieldset class="payment-methods"><legend>Choose a payment method</legend><?php foreach(['gcash'=>['account_balance_wallet','GCash','Pay using a mobile wallet'],'card'=>['credit_card','Credit / Debit Card','Pay using a card'],'bank_transfer'=>['account_balance','Bank Transfer','Pay using a bank transfer']] as $method=>$details): ?><label><input type="radio" name="payment_method" value="<?= $method ?>" <?= $method==='gcash'?'checked':'' ?>><span class="material-symbols-outlined" aria-hidden="true"><?= $details[0] ?></span><span><strong><?= $details[1] ?></strong><small><?= $details[2] ?></small></span></label><?php endforeach ?></fieldset><div class="student-actions"><button type="submit">Pay Now</button></div></form>
<?php elseif($pendingPayment): ?><div class="reservation-notice pending recovery-notice"><span class="material-symbols-outlined" aria-hidden="true">schedule</span><div><strong>You have an unfinished payment</strong><p>Continue your existing payment to complete your reservation payment.</p><div class="recovery-actions"><?php if($paymentEligible && is_string($pendingPayment['request_payload']??null) && $pendingPayment['request_payload']!==''): ?><form class="payment-recovery-form" method="post" action="<?= site_url('borrower/reservations/'.$id.'/payments') ?>"><?= csrf_field() ?><input type="hidden" name="payment_method" value="<?= esc($pendingPayment['payment_method'],'attr') ?>"><button type="submit" data-busy="Resuming payment...">Continue Payment</button></form><?php endif ?><form class="payment-recovery-form" method="post" action="<?= site_url('borrower/reservations/'.$id.'/payments/'.$pendingPayment['id'].'/verify') ?>"><?= csrf_field() ?><button type="submit" class="secondary" data-busy="Checking status...">Check Status</button></form></div></div></div>
<?php elseif(!$hasPaidPayment && in_array($reservation['status'],['rejected','cancelled','completed'],true)): ?><p>New payment attempts are unavailable for this reservation status.</p><?php elseif(!$formAccepted): ?><p>Payment is blocked until an administrator accepts the latest teacher-signed request form.</p><?php elseif($hasPaidPayment): ?><p class="reservation-notice success" role="status"><span class="material-symbols-outlined" aria-hidden="true">check_circle</span> Payment confirmed. Borrower cancellation is unavailable because refunds are not supported.</p><?php elseif($reservation['status']!=='approved'): ?><p>Payment is available only after administrator approval.</p><?php elseif(!$validPaymentTotal): ?><p>This reservation total cannot be processed by the payment gateway.</p><?php endif ?></section>
<section class="student-card student-wide"><h2>Administrator Decision</h2><?php if($reservation['reviewed_at']): ?><p><?= esc($reviewer['full_name']??'Facilities Office') ?> · <?= esc($displayTime($reservation['reviewed_at'])) ?> Manila</p><p class="description"><?= esc($reservation['admin_remarks']??'No remarks.') ?></p><?php else: ?><p>No administrator decision has been recorded.</p><?php endif ?></section><?php if($reservation['status']==='pending'): ?><section class="student-card"><h2>Reservation Actions</h2><form method="post" action="<?= site_url('borrower/reservations/'.$id.'/cancel') ?>"><?= csrf_field() ?><button type="submit" class="secondary">Cancel pending reservation</button></form></section><?php endif ?></div></div>
<?= $this->endSection() ?>
